mapper.select:
SELECT CHAT_ID, NUM, TYPE, CONTENT, ROLE, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT_MESSAGE
WHERE CHAT_ID = #{id}

    AND NUM >= #{minNum}


    AND NUM <= #{maxNum}



    AND CREATED_AT >= FROM_UNIXTIME(#{minTimestamp} / 1000)


    AND CREATED_AT <= FROM_UNIXTIME(#{maxTimestamp} / 1000)


ORDER BY NUM

    LIMIT #{maxAmount}

SELECT * FROM (
    SELECT CHAT_ID, NUM, TYPE, CONTENT, ROLE, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
    FROM T_CHAT_MESSAGE
    WHERE CHAT_ID = #{id}
    ORDER BY NUM DESC
    LIMIT #{maxAmount}
) RECENT
ORDER BY NUM

SELECT CHAT_ID, NUM, TYPE, CONTENT, ROLE, UNIX_TIMESTAMP(CREATED_AT) * 1000 CREATED_AT
FROM T_CHAT_MESSAGE
WHERE CHAT_ID = #{chatId} AND NUM = #{num}
